import React, { useEffect, useState } from 'react';
import { getFiles } from '../services/api'; 
import { Line } from 'react-chartjs-2';
import { Activity } from 'lucide-react';
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend } from 'chart.js';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend);

const Performance = () => {
  const [files, setFiles] = useState([]);

  useEffect(() => {
    const load = async () => { try { const res = await getFiles(); setFiles(res.data); } catch(e){} };
    load();
  }, []);

  // Filter Data
  const hybridData = files.map(f => f.mode === 'hybrid' ? f.metrics.total : null);
  const baselineData = files.map(f => f.mode !== 'hybrid' ? f.metrics.total : null);
  const labels = files.map((_, i) => `Sample ${i + 1}`);

  const chartData = {
    labels: labels,
    datasets: [
      {
        label: 'Hybrid PQC (Kyber+AES)',
        data: hybridData,
        borderColor: '#00ff9d',
        backgroundColor: '#00ff9d',
        tension: 0.4,
        spanGaps: true
      },
      {
        label: 'Baseline (RSA+AES)',
        data: baselineData,
        borderColor: '#ff0055',
        backgroundColor: '#ff0055',
        tension: 0.4,
        spanGaps: true
      }
    ]
  };

  const avgHybrid = (files.filter(f => f.mode === 'hybrid').reduce((a, b) => a + b.metrics.total, 0) / (files.filter(f => f.mode === 'hybrid').length || 1)).toFixed(2);

  return (
    <div className="p-8 h-full space-y-6">
       <h2 className="text-2xl font-bold text-white mb-4">Performance Metrics</h2>
       
       <div className="grid grid-cols-3 gap-6 h-[500px]">
           {/* MAIN GRAPH */}
           <div className="col-span-2 bg-scifi-panel border border-scifi-border p-6 rounded-xl">
               <h3 className="text-gray-400 text-xs uppercase tracking-wider mb-6 flex items-center gap-2"><Activity size={16}/> Encryption Latency (ms)</h3>
               <div className="h-80">
                   <Line data={chartData} options={{ responsive: true, maintainAspectRatio: false, scales: { y: { grid: { color: '#222' } } } }} />
               </div>
           </div>

           {/* STATS */}
           <div className="col-span-1 space-y-4">
               <MetricCard title="Avg. PQC Encap" value="0.04 ms" sub="Kyber-512" />
               <MetricCard title="Avg. AES Throughput" value="2.4 GB/s" sub="AES-NI Enabled" />
               <MetricCard title="Hybrid Latency" value={`${avgHybrid} ms`} sub="Total Time" />
               <MetricCard title="Integrity Check" value="SHA-256" sub="HMAC/GCM" />
           </div>
       </div>
    </div>
  );
};

const MetricCard = ({ title, value, sub }) => (
    <div className="bg-black border border-gray-800 p-6 rounded-xl text-center">
        <p className="text-gray-500 text-[10px] uppercase tracking-widest mb-2">{title}</p>
        <p className="text-3xl font-bold text-neon-green font-mono">{value}</p>
        <p className="text-gray-600 text-[10px] mt-1">{sub}</p>
    </div>
);

export default Performance;
